/**
 * VisualOdds admin sandbox catalog. All people, transactions, feeds, and metrics
 * below are synthetic. A status transition changes a local sandbox record only.
 */

export const ADMIN_ROLES = ['Owner', 'Developer', 'Data Operator', 'Support', 'Content Editor'];

const column = (key, label) => ({ key, label });
const NUMBER_BOUNDS = {
  amount: { min: 0 }, interval: { min: 1 }, minBooks: { min: 1 },
  vigLimit: { min: 0, max: 100 }, liquidity: { min: 0 }, fee: { min: 0, max: 100 },
  slipSize: { min: 1 }, stake: { min: 0 }, missing: { min: 0 }, limit: { min: 0 },
};
const COUNT_FIELDS = new Set(['interval', 'minBooks', 'slipSize', 'missing', 'limit']);
const field = (key, label, type = 'text', required = false) => {
  const valueType = type === 'number' && COUNT_FIELDS.has(key) ? 'integer' : type;
  return { key, label, type: valueType, required, ...(['number', 'integer'].includes(valueType) ? NUMBER_BOUNDS[key] || { min: 0 } : {}) };
};
const choice = (key, label, options) => ({ key, label, type: 'select', options, required: true });
const action = (id, label, targetStatus, sensitive = false, metadata = {}) => ({ id, label, targetStatus, sensitive, ...metadata });
const request = (id, label, targetStatus, sensitive = false, appliesTo) => action(id, label, targetStatus, sensitive, { requestOnly: true, ...(appliesTo ? { appliesTo } : {}) });
const record = (id, name, status, values, details = {}) => ({ id, name, status, ...values, details });

function section(id, label, group, icon, description, columns, fields, statuses, actions) {
  return {
    id, label, group, icon, description,
    columns: [column('name', 'Name'), ...columns, column('status', 'Status')],
    fields: [field('name', 'Name', 'text', true), ...fields, choice('status', 'Status', statuses.filter(status => !actions.some(item => item.requestOnly && item.targetStatus === status)))],
    actions,
    searchPlaceholder: `Search ${label.toLowerCase()} by name, ID, or details…`,
    emptyMessage: `No ${label.toLowerCase()} match your search or filters.`,
  };
}

